import { mkdirSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { sanitizeFilename } from "./bestEffortFs.js";
import { resolveReplayItemIdentity } from "./replayItemIdentity.js";
export function externalizeProgressEvent(event, itemsDir, index) {
    if (!event.item) {
        return { event };
    }
    const item = event.item;
    const hasPayload = hasValue(item.input) ||
        hasValue(item.result) ||
        hasValue(item.originalOutput) ||
        hasValue(item.tokens) ||
        hasValue(item.model) ||
        hasValue(item.dbSnapshotRef);
    if (!hasPayload) {
        return { event };
    }
    // Same key as externalizeCompleteResult so the final write overwrites this
    // live file rather than making a second file for the same item.
    const key = item.originalTraceId ?? item.replayTraceId ?? `progress-${index}`;
    const itemPath = writeItemFile(itemsDir, key, {
        testRunId: event.testRunId ?? null,
        originalTraceId: item.originalTraceId ?? null,
        // Deprecated alias; traceId is null mid-progress (server id not yet known).
        sourceTraceId: item.originalTraceId ?? null,
        traceId: null,
        replayTraceId: item.replayTraceId ?? null,
        input: item.input,
        result: item.result,
        originalOutput: item.originalOutput,
        error: item.error ?? null,
        durationMs: item.durationMs ?? null,
        originalDurationMs: item.originalDurationMs ?? null,
        originalTokens: item.originalTokens ?? null,
        originalModel: item.originalModel ?? null,
        dbBranchTimings: item.dbBranchTimings ?? null,
        tokens: item.tokens,
        model: item.model,
        dbSnapshotRef: item.dbSnapshotRef,
        traceOutline: item.traceOutline ?? null,
        originalTraceOutline: item.originalTraceOutline ?? null,
    });
    if (!itemPath) {
        return { event };
    }
    return {
        itemPath,
        event: {
            ...event,
            item: {
                originalTraceId: item.originalTraceId,
                replayTraceId: item.replayTraceId,
                error: item.error,
                durationMs: item.durationMs,
                itemPath,
            },
        },
    };
}
export function externalizeCompleteResult(result, itemsDir) {
    if (!result || typeof result !== "object") {
        return [];
    }
    const rec = result;
    if (!Array.isArray(rec.items)) {
        return [];
    }
    const refs = [];
    for (let i = 0; i < rec.items.length; i++) {
        const rawItem = rec.items[i];
        if (!rawItem || typeof rawItem !== "object") {
            continue;
        }
        const item = rawItem;
        const identity = resolveReplayItemIdentity(item);
        const durationMs = item.durationMs ?? item.duration_ms;
        // persistKey matches externalizeProgressEvent so both writes hit one file.
        const itemPath = writeItemFile(itemsDir, identity.persistKey ?? `complete-${i}`, {
            testRunId: typeof rec.testRunId === "string"
                ? rec.testRunId
                : typeof rec.test_run_id === "string"
                    ? rec.test_run_id
                    : null,
            originalTraceId: identity.originalTraceId,
            sourceTraceId: identity.originalTraceId,
            traceId: identity.traceId,
            replayTraceId: null,
            input: item.input,
            result: item.result,
            originalOutput: item.originalOutput ?? item.original_output,
            error: item.error ?? null,
            durationMs: typeof durationMs === "number" ? durationMs : null,
            originalDurationMs: item.originalDurationMs ?? item.original_duration_ms ?? null,
            originalTokens: item.originalTokens ?? item.original_tokens ?? null,
            originalModel: item.originalModel ?? item.original_model ?? null,
            tokens: item.tokens,
            model: item.model,
            dbSnapshotRef: item.dbSnapshotRef ?? item.db_snapshot_ref,
            dbBranchTimings: item.dbBranchTimings ?? item.db_branch_timings ?? null,
            traceOutline: item.traceOutline ?? item.trace_outline ?? null,
            originalTraceOutline: item.originalTraceOutline ?? item.original_trace_outline ?? null,
        });
        if (!itemPath) {
            continue;
        }
        refs.push({
            originalTraceId: identity.originalTraceId,
            traceId: identity.traceId,
            replayTraceId: null,
            itemPath,
            error: typeof item.error === "string" ? item.error : null,
            durationMs: typeof durationMs === "number" ? durationMs : null,
        });
    }
    return refs;
}
export function buildCompleteSummary(result) {
    if (!result || typeof result !== "object") {
        return {};
    }
    const rec = result;
    const items = Array.isArray(rec.items) ? rec.items : [];
    return {
        ...(typeof rec.testRunId === "string" ? { testRunId: rec.testRunId } : {}),
        ...(typeof rec.test_run_id === "string"
            ? { testRunId: rec.test_run_id }
            : {}),
        ...(typeof rec.testRunUrl === "string"
            ? { testRunUrl: rec.testRunUrl }
            : {}),
        ...(typeof rec.test_run_url === "string"
            ? { testRunUrl: rec.test_run_url }
            : {}),
        itemCount: items.length,
    };
}
function writeItemFile(itemsDir, key, payload) {
    try {
        mkdirSync(itemsDir, { recursive: true });
        const filename = `${sanitizeFilename(key)}.json`;
        const target = join(itemsDir, filename);
        const tmp = `${target}.tmp-${process.pid}-${Date.now()}`;
        writeFileSync(tmp, `${JSON.stringify(payload)}\n`);
        renameSync(tmp, target);
        return target;
    }
    catch {
        return null;
    }
}
function hasValue(value) {
    return value !== undefined;
}
